file_editor: {"command": "create", "file_text": "import os
import re
from pathlib import Path
from collections import Counter

import pytesseract
from PIL import Image, ImageOps
from openpyxl import Workbook, load_workbook

IMG_DIR = Path("/app/workspace/dataset/img")
OUT_XLSX = Path("/app/workspace/stat_ocr.xlsx")

TIER_KEYWORDS = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    ["TOTAL", "AMOUNT", "TOTAL DUE", "AMOUNT DUE",
     "BALANCE DUE", "NETT TOTAL", "NET TOTAL"],
]

EXCLUSION_PATTERNS = [
    r"\bSUB\s*TOTAL\b", r"\bSUBTOTAL\b", r"\bTAX\b", r"\bGST\b", r"\bSST\b",
    r"\bDISCOUNT\b", r"\bCHANGE\b", r"\bCASH\s+TENDERED\b",
]
EXCLUDE_RE = re.compile("|".join(EXCLUSION_PATTERNS), re.IGNORECASE)

PAYMENT_RE = re.compile(
    r"\b(CASH|VISA|MASTER\s*CARD|MASTERCARD|CARD|PAYMENT|TENDERED|RECEIVED|CHANGE)\b",
    re.IGNORECASE,
)

NUM_RE = re.compile(r"(?<![\d.])(\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2})(?!\d)")

MONTHS = {m.upper(): i for i, m in enumerate(
    ["JAN", "FEB", "MAR", "APR", "MAY", "JUN", "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"], 1)}

DATE_PATTERNS = [
    re.compile(r"\b(\d{1,2})[/-](\d{1,2})[/-](\d{4})\b"),       # DD/MM/YYYY
    re.compile(r"\b(\d{1,2})[/-](\d{1,2})[/-](\d{2})\b"),       # DD/MM/YY
    re.compile(r"\b(\d{4})-(\d{1,2})-(\d{1,2})\b"),             # YYYY-MM-DD
    re.compile(r"\b(\d{1,2})\s+([A-Za-z]{3,9})\s+(\d{4})\b"),   # DD Mon YYYY
]
DATE_LABEL_RE = re.compile(r"\b(DATE|TARIKH|TANGGAL)\b", re.IGNORECASE)


def ocr_variants(path, escalate=False):
    im = Image.open(path)
    variants = []
    variants.append(("default", pytesseract.image_to_string(im)))
    g = ImageOps.autocontrast(ImageOps.grayscale(im))
    variants.append(("gray", pytesseract.image_to_string(g)))
    if escalate:
        for scale in (2, 3):
            big = g.resize((g.width * scale, g.height * scale), Image.LANCZOS)
            for psm in (4, 6, 11):
                variants.append(
                    (f"s{scale}_psm{psm}",
                     pytesseract.image_to_string(big, config=f"--psm {psm}"))
                )
    return variants


def parse_num(s):
    return float(s.replace(",", ""))


def validate_date(y, m, d):
    try:
        from datetime import date
        date(y, m, d)
        return True
    except Exception:
        return False


def extract_date_candidates(text):
    """Return list of (iso_date, is_labelled, line_idx). Avoids time-adjacent tokens."""
    out = []
    for i, line in enumerate(text.splitlines()):
        labelled = bool(DATE_LABEL_RE.search(line))
        for pat_idx, pat in enumerate(DATE_PATTERNS):
            for m in pat.finditer(line):
                try:
                    if pat_idx == 0:  # DD/MM/YYYY
                        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                    elif pat_idx == 1:  # DD/MM/YY
                        d, mo, y = int(m.group(1)), int(m.group(2)), 2000 + int(m.group(3))
                    elif pat_idx == 2:  # YYYY-MM-DD
                        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
                    else:  # DD Mon YYYY
                        d = int(m.group(1))
                        mon = m.group(2).upper()[:3]
                        if mon not in MONTHS:
                            continue
                        mo = MONTHS[mon]
                        y = int(m.group(3))
                    if not (1 <= mo <= 12 and 1 <= d <= 31):
                        continue
                    if not validate_date(y, mo, d):
                        continue
                    # Check time-adjacency: skip if the match is immediately followed/preceded by ":NN"
                    span = m.span()
                    after = line[span[1]:span[1] + 3]
                    before = line[max(0, span[0] - 3):span[0]]
                    if re.match(r":\d{2}", after) or re.search(r"\d{2}:$", before):
                        # treat as time-adjacent; still allow if date pattern itself contains '-'/'/'
                        pass
                    iso = f"{y:04d}-{mo:02d}-{d:02d}"
                    out.append((iso, labelled, i))
                except Exception:
                    continue
    return out


def choose_date(all_passes_candidates):
    """all_passes_candidates: list over passes, each a list of (iso,labelled,line_idx)."""
    # Prefer labelled candidates: pick from the pass that has any labelled candidate.
    for cands in all_passes_candidates:
        labelled = [c for c in cands if c[1]]
        if labelled:
            return labelled[0][0]
    # Fallback: earliest valid non-time-adjacent date appearing in >=2 passes.
    counts = Counter()
    for cands in all_passes_candidates:
        seen_in_pass = set()
        for iso, _, _ in cands:
            if iso in seen_in_pass:
                continue
            seen_in_pass.add(iso)
            counts[iso] += 1
    multi = [iso for iso, c in counts.items() if c >= 2]
    if multi:
        # earliest by occurrence in first pass
        for cands in all_passes_candidates:
            for iso, _, _ in cands:
                if iso in multi:
                    return iso
    return None


def extract_tier_candidates(text):
    """Return dict tier_idx -> list of float values (in order of appearance)."""
    lines = text.splitlines()
    tier_vals = {i: [] for i in range(len(TIER_KEYWORDS))}
    for i, line in enumerate(lines):
        up = line.upper()
        if EXCLUDE_RE.search(up):
            continue
        if PAYMENT_RE.search(up):
            # If payment-related words appear, exclude this line as tier source
            continue
        for tier_idx, kws in enumerate(TIER_KEYWORDS):
            matched = any(kw in up for kw in kws)
            if not matched:
                continue
            nums = NUM_RE.findall(line)
            if nums:
                tier_vals[tier_idx].append((parse_num(nums[-1]), i))
            else:
                # look at next non-excluded line
                for j in range(i + 1, min(i + 3, len(lines))):
                    nxt = lines[j]
                    nup = nxt.upper()
                    if EXCLUDE_RE.search(nup) or PAYMENT_RE.search(nup):
                        continue
                    if not nxt.strip():
                        continue
                    nnums = NUM_RE.findall(nxt)
                    if nnums:
                        tier_vals[tier_idx].append((parse_num(nnums[-1]), j))
                    break
            break  # don't double-match tiers for same line
    return tier_vals


def extract_anchors(text):
    """Return list of anchor float values from the text."""
    anchors = []
    lines = text.splitlines()
    cash_val = None
    change_val = None
    for line in lines:
        up = line.upper()
        nums = NUM_RE.findall(line)
        if not nums:
            continue
        last = parse_num(nums[-1])
        if "SUBTOTAL" in up or "SUB TOTAL" in up:
            anchors.append(last)
        elif "TOTAL INCL" in up and "GST" in up:
            anchors.append(last)
        elif re.search(r"\bROUND(ED|ING)?\b", up) or "NET TOTAL" in up or "TOTAL ROUNDED" in up:
            anchors.append(last)
        elif re.search(r"\b(VISA|MASTERCARD|MASTER\s*CARD|PAYMENT)\b", up) and "CHANGE" not in up and "TENDERED" not in up:
            anchors.append(abs(last))
        elif "CASH" in up and "CHANGE" not in up and "TENDERED" not in up:
            cash_val = last
        if "CHANGE" in up:
            change_val = last
    if cash_val is not None and change_val is None:
        anchors.append(abs(cash_val))
    if cash_val is not None and change_val is not None:
        anchors.append(abs(cash_val - change_val))
    return anchors


def choose_total(per_pass_tiers, per_pass_anchors):
    # Pick highest-priority tier that produced any candidate across passes.
    all_anchors = []
    for a in per_pass_anchors:
        all_anchors.extend(a)
    chosen_tier = None
    for t_idx in range(len(TIER_KEYWORDS)):
        if any(per_pass_tiers[p].get(t_idx) for p in range(len(per_pass_tiers))):
            chosen_tier = t_idx
            break

    if chosen_tier is None:
        # anchor-only fallback: >=2 anchors agree within 0.05
        if len(all_anchors) >= 2:
            for i, a in enumerate(all_anchors):
                agree = [b for b in all_anchors if abs(a - b) <= 0.05]
                if len(agree) >= 2:
                    return a
        return None

    # Collect candidates from the chosen tier across passes with their pass index.
    cand_entries = []  # (value, pass_idx, line_idx)
    for p_idx, tiers in enumerate(per_pass_tiers):
        for val, line_idx in tiers.get(chosen_tier, []):
            cand_entries.append((val, p_idx, line_idx))

    if not cand_entries:
        return None

    # Outlier filter: drop candidates whose leading digit disagrees with every anchor's leading digit,
    # or whose value exceeds 2x the maximum anchor.
    def leading_digit(x):
        s = f"{x:.2f}".lstrip("0").lstrip(".")
        for ch in s:
            if ch.isdigit():
                return ch
        return None

    if all_anchors:
        anchor_lds = {leading_digit(a) for a in all_anchors}
        max_anchor = max(all_anchors)
        filtered = []
        for e in cand_entries:
            v = e[0]
            if leading_digit(v) not in anchor_lds and v > 2 * max_anchor:
                continue
            if v > 2 * max_anchor and leading_digit(v) not in anchor_lds:
                continue
            filtered.append(e)
        if filtered:
            cand_entries = filtered

    # Prefer a value equal (within 0.05) to any anchor.
    if all_anchors:
        anchor_matched = [e for e in cand_entries
                          if any(abs(e[0] - a) <= 0.05 for a in all_anchors)]
        if anchor_matched:
            # most-frequent-across-passes among those
            vcount = Counter(round(e[0], 2) for e in anchor_matched)
            best = vcount.most_common(1)[0][0]
            return best

    # Else value appearing in the most passes.
    pass_count = {}
    for v, p_idx, _ in cand_entries:
        key = round(v, 2)
        pass_count.setdefault(key, set()).add(p_idx)
    if pass_count:
        best = max(pass_count.items(), key=lambda kv: (len(kv[1]), -list(pass_count).index(kv[0])))
        return best[0]
    return cand_entries[0][0]


def process_image(path):
    variants = ocr_variants(path, escalate=False)
    per_pass_tiers = [extract_tier_candidates(t) for _, t in variants]
    per_pass_anchors = [extract_anchors(t) for _, t in variants]
    all_date_cands = [extract_date_candidates(t) for _, t in variants]

    total = choose_total(per_pass_tiers, per_pass_anchors)
    date = choose_date(all_date_cands)

    need_escalate = total is None or date is None
    if not need_escalate and total is not None:
        anchors = [a for lst in per_pass_anchors for a in lst]
        if anchors and not any(abs(total - a) <= 0.05 for a in anchors):
            # Check if any tier candidate agrees with an anchor; if none at all, escalate.
            tier_vals = []
            for tiers in per_pass_tiers:
                for lst in tiers.values():
                    tier_vals.extend(v for v, _ in lst)
            if tier_vals and not any(abs(v - a) <= 0.05 for v in tier_vals for a in anchors):
                need_escalate = True

    if need_escalate:
        variants = ocr_variants(path, escalate=True)
        per_pass_tiers = [extract_tier_candidates(t) for _, t in variants]
        per_pass_anchors = [extract_anchors(t) for _, t in variants]
        all_date_cands = [extract_date_candidates(t) for _, t in variants]
        total = choose_total(per_pass_tiers, per_pass_anchors)
        date = choose_date(all_date_cands)

    total_str = f"{total:.2f}" if total is not None else None
    return date, total_str


def main():
    files = sorted(p for p in IMG_DIR.iterdir()
                   if p.suffix.lower() in {".jpg", ".jpeg", ".png"})
    rows = []
    for p in files:
        try:
            d, t = process_image(p)
        except Exception as e:
            print(f"ERROR {p.name}: {e}")
            d, t = None, None
        print(f"{p.name}: date={d}, total={t}")
        rows.append((p.name, d, t))

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for fn, d, t in rows:
        ws.append([fn, d, t])
    wb.save(OUT_XLSX)

    # Validation anchor: reopen, coerce empty strings to None, assert.
    wb = load_workbook(OUT_XLSX)
    assert wb.sheetnames == ["results"], wb.sheetnames
    ws = wb["results"]
    for row in ws.iter_rows():
        for cell in row:
            if isinstance(cell.value, str) and cell.value.strip() == "":
                cell.value = None
    wb.save(OUT_XLSX)

    wb = load_workbook(OUT_XLSX)
    ws = wb["results"]
    data = list(ws.iter_rows(values_only=True))
    assert data[0] == ("filename", "date", "total_amount"), data[0]
    assert len(data) - 1 == len(files), (len(data) - 1, len(files))
    date_re = re.compile(r"^\d{4}-\d{2}-\d{2}$")
    total_re = re.compile(r"^\d+\.\d{2}$")
    for fn, d, t in data[1:]:
        if d is not None:
            assert date_re.match(d), (fn, d)
        if t is not None:
            assert total_re.match(t), (fn, t)
        assert d != "" and t != ""
    print("validation OK")


if __name__ == "__main__":
    main()
